final class MarketingEmailSettings {
 public function key():string{return 'marketing_email:'.hash('sha256',app(MarketingPosts::class)->merchant());}
 public function raw():array {return StoreSetting::where('key',$this->key())->first()?->value??[];}
 public function summary(bool $private=false):array {$s=$this->raw();$out=['version'=>$s['version']??0,'verified'=>!empty($s['verified_at']),'verified_at'=>$s['verified_at']??null,'feedback_connected'=>false,'complaint_connected'=>false,'can_check_bounces'=>(bool)config('marketing.email_bounce_enabled',false),'bounces'=>app(MarketingEmailBounce::class)->status(),'domain_verified'=>false,'bulk_enabled'=>(bool)config('marketing.email_bulk_enabled'),'from_name'=>$s['from_name']??config('mail.from.name'),'from_address'=>$s['from_address']??config('mail.from.address'),'reply_to'=>$s['reply_to']??'','minute_limit'=>$s['minute_limit']??10,'hour_limit'=>$s['hour_limit']??100,'day_limit'=>min($s['day_limit']??1000,1000),'mailbox_ceiling'=>1000,'unit_minor'=>$s['unit_minor']??null,'currency'=>$s['currency']??'USD','last_check'=>$s['last_check']??null,'check_result'=>$s['check_result']??'not_checked'];if($private)$out+=['host'=>$s['host']??config('mail.mailers.smtp.host'),'port'=>$s['port']??config('mail.mailers.smtp.port',587),'encryption'=>$s['encryption']??((int)config('mail.mailers.smtp.port',587)===465?'ssl':'tls'),'username'=>$s['username']??'','has_password'=>!empty($s['password']),'allowed_hosts'=>$this->hosts(),'can_check'=>(bool)config('marketing.email_connection_test_enabled')];return $out;}
 public function hosts():array {return array_values(array_unique(array_filter(array_map('strtolower',array_merge(config('marketing.email_smtp_hosts',[]),[(string)config('mail.mailers.smtp.host')])))));}
 public function save(array $d):array {return DB::transaction(function()use($d){StoreSetting::firstOrCreate(['key'=>$this->key()],['value'=>[]]);$row=StoreSetting::where('key',$this->key())->lockForUpdate()->first();$old=$row->value??[];abort_unless(($old['version']??0)===$d['version'],409,'These settings changed. Reload before saving.');abort_if(DB::table('marketing_email_batches')->where('merchant_key',app(MarketingPosts::class)->merchant())->whereIn('state',['queued','processing'])->exists(),409,'Wait for the current email campaign to finish before changing its settings.');abort_unless($d['day_limit']<=1000,422,'This email route supports up to 1,000 attempts in a rolling 24-hour period.');$d['host']=strtolower($d['host']);abort_unless(($d['port']===465&&$d['encryption']==='ssl')||($d['port']===587&&$d['encryption']==='tls'),422,'Use port 465 with SSL or port 587 with STARTTLS.');abort_unless(in_array($d['host'],$this->hosts(),true)&&!filter_var($d['host'],FILTER_VALIDATE_IP)&&!in_array($d['host'],['localhost'],true),422,'Choose an email server approved for this store.');abort_unless($d['minute_limit']<=$d['hour_limit']&&$d['hour_limit']<=$d['day_limit'],422,'Hourly and daily limits must be at least as large as the shorter limits.');abort_if(preg_match('/[\r\n]/',$d['from_name'].$d['username']),422,'Use a single line for sender details.');$password=trim($d['password']??'')!==''?Crypt::encryptString($d['password']):($old['password']??null);abort_unless($password,422,'Enter the SMTP password.');$next=array_intersect_key($d,array_flip(['host','port','encryption','username','from_name','from_address','reply_to','minute_limit','hour_limit','day_limit','unit_minor','currency']));$next['password']=$password;$next['version']=($old['version']??0)+1;$next['verified_at']=null;$next['check_result']='not_checked';$next['last_check']=null;$row->update(['value'=>$next]);return $this->summary(true);});}
 public function check(int $version):array {abort_unless(config('marketing.email_connection_test_enabled',false),409,'Connection checks are not available yet. Your saved settings are retained.');$s=$this->raw();abort_unless(($s['version']??0)===$version&&$version>0,409,'Save and reload these settings before checking.');$ok=false;try{app(MarketingSmtpProbe::class)->check($this->transport($s));$ok=true;}catch(\Throwable){/* Provider diagnostics may contain credentials; never return or persist them. */}return DB::transaction(function()use($version,$ok){$row=StoreSetting::where('key',$this->key())->lockForUpdate()->first();$s=$row?->value??[];abort_unless(($s['version']??0)===$version,409,'The settings changed during the check. Check the saved version again.');$s['verified_at']=$ok?now()->toIso8601String():null;$s['last_check']=now()->toIso8601String();$s['check_result']=$ok?'connected':'connection_failed';$row->update(['value'=>$s]);return $this->summary(true);});}
 public function transport(?array $s=null):array {$s=$s??$this->raw();abort_unless(!empty($s['password']),409,'Save the email connection first.');abort_unless(in_array($s['host'],$this->hosts(),true),409,'This email server is no longer approved.');return ['transport'=>'smtp','scheme'=>$s['encryption']==='ssl'?'smtps':'smtp','host'=>$s['host'],'port'=>$s['port'],'username'=>$s['username'],'password'=>Crypt::decryptString($s['password']),'timeout'=>10,'require_tls'=>true];}
 public function version():int{return $this->raw()['version']??0;}
 public function price():?int {$s=$this->raw();$v=array_key_exists('unit_minor',$s)?$s['unit_minor']:config('marketing.email_bulk_unit_minor');return is_int($v)&&$v>=0?$v:null;}
 public function currency():string{return $this->raw()['currency']??config('marketing.email_bulk_currency','USD');}
 public function from():array {$s=$this->raw();return ['address'=>$s['from_address']??config('mail.from.address'),'name'=>$s['from_name']??config('mail.from.name')];}
 public function ready(int $version):bool {$s=$this->raw();return $version>0&&($s['version']??0)===$version&&!empty($s['verified_at'])&&$this->price()!==null&&in_array($s['host'],$this->hosts(),true);}
 public function bindMailer():void {config(['mail.mailers.marketing_campaign'=>$this->transport()]);Mail::purge('marketing_campaign');}
 public function quotaKey(array $s):string{return hash('sha256',strtolower(trim($s['host'])).'|'.strtolower(trim($s['username'])));}
 public function reserve(string $delivery,int $version):bool {return DB::transaction(function()use($delivery,$version){$row=StoreSetting::where('key',$this->key())->lockForUpdate()->first();if(!$row||!$this->ready($version))return false;$s=$row->value;$merchant=app(MarketingPosts::class)->merchant();$bucket=$this->quotaKey($s);$q=DB::table('marketing_email_send_reservations')->where(fn($b)=>$b->where('quota_key',$bucket)->orWhere(fn($legacy)=>$legacy->where('merchant_key',$merchant)->whereNull('quota_key')));if((clone $q)->where('delivery_id',$delivery)->exists())return true;foreach(['minute'=>'minute_limit','hour'=>'hour_limit','day'=>'day_limit'] as $period=>$limit){$start=match($period){'minute'=>now()->subMinute(),'hour'=>now()->subHour(),default=>now()->subDay()};$cap=$period==='day'?min($s[$limit],1000):$s[$limit];if((clone $q)->where('created_at','>',$start)->count()>=$cap)return false;}DB::table('marketing_email_send_reservations')->insert(['delivery_id'=>$delivery,'merchant_key'=>$merchant,'quota_key'=>$bucket,'created_at'=>now()]);return true;});}
}
